using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CrimsonVaultOmenData", menuName = "Data/Battle/Omens System/Omen Data/Event/CrimsonVaultOmenData")]
public class CrimsonVaultOmenData : OmenData
{
	[Header("CodexOfBurdensOmenData Omen")]
	[SerializeField]
	private OmenData destroyedVaultOmenData;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private PlayerCurrentOmens playerCurrentOmens;

	[SerializeField]
	private OmensListsList omensListsList;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.CrimsonVaultsReachedGroundZeroActions.Add(GroundZeroReached);
		ReferenceSingleton<MiscOmensHandler>.Instance.CrimsonVaultsReachedGroundZeroInstances.Add(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.CrimsonVaultsReachedGroundZeroActions.Remove(GroundZeroReached);
	}

	public void GroundZeroReached(OmenInstance omenInstance)
	{
		OmenRemoved();
		RuntimeOmenData item = new RuntimeOmenData(destroyedVaultOmenData, 0);
		int runtimeOmenIndex = playerCurrentOmens.GetRuntimeOmenIndex(this);
		playerCurrentOmens.RuntimeOmens.RemoveAt(runtimeOmenIndex);
		playerCurrentOmens.RuntimeOmens.Insert(runtimeOmenIndex, item);
		omenInstance.Initialize(destroyedVaultOmenData);
		destroyedVaultOmenData.Initialize(omenInstance);
		omenInstance.EnqueueOmenFeedbackAndPlay();
		omensListsList.BlessingDiscovered(destroyedVaultOmenData);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(ActionValue);
		saveSystem.SaveOmenAndGold();
	}
}
